    if(relation.linked)audit(actor,'RELACIONAR_USUARIO_CONDUCTOR_CHECKIN','CHECKIN',`Usuario ${users[0].CORREO} vinculado al conductor ${driver.NOMBRE||driver.ID}.`,driver.ID);
