    let userId=String(result.USUARIO_ID||'').trim(),email=localEmail(result.CORREO);
    const completarDesdeUsuario=user=>{if(!String(result.NOMBRE||'').trim())result.NOMBRE=String(user?.NOMBRE||'').trim();if(!localEmail(result.CORREO))result.CORREO=localEmail(user?.CORREO);if(!String(result.TELEFONO||'').trim())result.TELEFONO=String(user?.TELEFONO||'').trim();};
