  function localNexoText(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[.,;:!¡¿?\"'()_\/\-]+/g,' ').replace(/\s+/g,' ').trim();}
