    const alertRows=alerts.slice(0,8).map(row=>`<article class="notification-card"><header><div><h4>${esc(row.TITULO||'Alerta')}</h4><p>${esc(row.MENSAJE||'')}</p></div>${status(row.NIVEL||'Alerta')}</header><div class="route-meta"><span>${fmtDate(row.FECHA_HORA||row.CREADO_EN,true)}</span><span>${esc(row.MODULO||'Sistema')}</span></div>${puedeMarcarAlertaFila(row)?`<button class="link-button" data-read-alert="${row.ID}" type="button">Marcar como leída</button>`:'<span class="status warning">Pendiente</span>'}</article>`).join('');
