    openModal();const form=$('#fuelForm'),assignment=form.elements.VINCULO_ASIGNACION,manual=$('[data-fuel-admin-manual]',form);enlazarCargaArchivo(form,'fuel');
    const campoFechaHora=form.elements.FECHA_HORA;if(campoFechaHora){campoFechaHora.type='text';campoFechaHora.inputMode='numeric';campoFechaHora.maxLength=16;campoFechaHora.pattern='\\d{2}/\\d{2}/\\d{4}:\\d{2}:\\d{2}';campoFechaHora.placeholder='DD/MM/AAAA:HH:MM';campoFechaHora.value=fmtDate(record?.FECHA_HORA||new Date(),true);}
    form.addEventListener('formdata',evento=>{if(campoFechaHora)evento.formData.set('FECHA_HORA',fechaVisualIso(campoFechaHora.value,true));});
    const applyLink=()=>{const value=assignment.value,item=items.find(row=>row.key===value);if(item){form.elements.VEHICULO_ID.value=item.vehicleId||'';form.elements.CONDUCTOR_ID.value=item.driverId||'';form.elements.OPERACION_ID.value=item.operationId||'';form.elements.RUTA_ID.value=item.routeId||'';manual?.classList.add('hidden');}else if(value==='ADMIN'&&admin){manual?.classList.remove('hidden');form.elements.OPERACION_ID.value='';form.elements.RUTA_ID.value='';form.elements.VEHICULO_ID.value=form.elements.VEHICULO_MANUAL_ID.value||'';form.elements.CONDUCTOR_ID.value=form.elements.CONDUCTOR_MANUAL_ID.value||'';}else{form.elements.VEHICULO_ID.value='';form.elements.CONDUCTOR_ID.value='';form.elements.OPERACION_ID.value='';form.elements.RUTA_ID.value='';manual?.classList.add('hidden');} $('[data-fuel-linked-vehicle]',form).textContent=fuelName('vehicles',form.elements.VEHICULO_ID.value,'Pendiente de selección');$('[data-fuel-linked-driver]',form).textContent=fuelName('drivers',form.elements.CONDUCTOR_ID.value,'Pendiente de selección');const vehicle=vehicles.find(row=>String(row.ID)===String(form.elements.VEHICULO_ID.value));if(vehicle&&form.elements.KILOMETRAJE&&!form.elements.KILOMETRAJE.value)form.elements.KILOMETRAJE.value=vehicle.KM_ACTUAL??vehicle.KILOMETRAJE??'';};
    assignment.addEventListener('change',applyLink);if(admin){form.elements.VEHICULO_MANUAL_ID?.addEventListener('change',applyLink);form.elements.CONDUCTOR_MANUAL_ID?.addEventListener('change',applyLink);}applyLink();
    const paint=()=>{$('[data-fuel-total] b',form).textContent=clp(Number(form.elements.LITROS.value||0)*Number(form.elements.PRECIO_LITRO.value||0));};form.elements.LITROS.addEventListener('input',paint);form.elements.PRECIO_LITRO.addEventListener('input',paint);$('[data-cancel-modal]',form).addEventListener('click',closeModal);form.addEventListener('submit',event=>saveFuel(event,record?.ID||''));
