      const programar=(espera=180)=>{pintarEstadoFiltrosReportesKpi(true);if(temporizadorFiltrosReportesKpi)clearTimeout(temporizadorFiltrosReportesKpi);temporizadorFiltrosReportesKpi=setTimeout(()=>{temporizadorFiltrosReportesKpi=null;if(currentSection==='reports')pintarKpisReportes(true);},espera);};
